# ---------------------------------------------------------------------------
# Target name resolution (local databases)
# ---------------------------------------------------------------------------

def resolve_target_name(raw_name: str) -> Optional[str]:
    """
    Resolve a target name using local catalogs.
    Returns the full common name if found, or None.

    Checks Messier, NGC, IC, Sh2, LBN, PGC, RCW, Abell, Arp catalogs.
    """
    if not raw_name:
        return None

    name = raw_name.strip()
    name_upper = name.upper().strip()

    # Direct match in databases
    if name in MESSIER_DATABASE:
        return MESSIER_DATABASE[name]
    if name in EXTENDED_ASTRONOMICAL_DATABASE:
        return EXTENDED_ASTRONOMICAL_DATABASE[name]
    if name in ARP_DATABASE:
        return ARP_DATABASE[name]

    # Messier: M 31, M31, Messier 31
    m_match = re.match(r'^(?:M(?:ESSIER)?\s*)(\d+)$', name_upper)
    if m_match:
        num = int(m_match.group(1))
        key = f"M{num}"
        if key in MESSIER_DATABASE:
            return MESSIER_DATABASE[key]

    # NGC: NGC 7000, NGC7000
    ngc_match = re.match(r'^(?:NGC\s*)(\d+[A-Z]?)$', name_upper)
    if ngc_match:
        key = f"NGC {ngc_match.group(1)}"
        if key in EXTENDED_ASTRONOMICAL_DATABASE:
            return EXTENDED_ASTRONOMICAL_DATABASE[key]

    # IC: IC 1396, IC1396
    ic_match = re.match(r'^(?:IC\s*)(\d+[A-Z]?)$', name_upper)
    if ic_match:
        key = f"IC {ic_match.group(1)}"
        if key in EXTENDED_ASTRONOMICAL_DATABASE:
            return EXTENDED_ASTRONOMICAL_DATABASE[key]

    # Sh2: Sh2-240, SH2 240
    sh2_match = re.match(r'^(?:SH2?[-\s]*)(\d+)$', name_upper)
    if sh2_match:
        key = f"Sh2-{sh2_match.group(1)}"
        if key in EXTENDED_ASTRONOMICAL_DATABASE:
            return EXTENDED_ASTRONOMICAL_DATABASE[key]

    # LBN: LBN 437
    lbn_match = re.match(r'^(?:LBN\s*)(\d+)$', name_upper)
    if lbn_match:
        key = f"LBN {lbn_match.group(1)}"
        if key in EXTENDED_ASTRONOMICAL_DATABASE:
            return EXTENDED_ASTRONOMICAL_DATABASE[key]

    # PGC
    pgc_match = re.match(r'^(?:PGC\s*)(\d+)$', name_upper)
    if pgc_match:
        key = f"PGC {pgc_match.group(1)}"
        if key in EXTENDED_ASTRONOMICAL_DATABASE:
            return EXTENDED_ASTRONOMICAL_DATABASE[key]

    # RCW
    rcw_match = re.match(r'^(?:RCW\s*)(\d+)$', name_upper)
    if rcw_match:
        key = f"RCW {rcw_match.group(1)}"
        if key in EXTENDED_ASTRONOMICAL_DATABASE:
            return EXTENDED_ASTRONOMICAL_DATABASE[key]

    # Abell
    abell_match = re.match(r'^(?:ABELL\s*)(\d+)$', name_upper)
    if abell_match:
        key = f"Abell {abell_match.group(1)}"
        if key in EXTENDED_ASTRONOMICAL_DATABASE:
            return EXTENDED_ASTRONOMICAL_DATABASE[key]

    # Arp
    arp_match = re.match(r'^(?:ARP\s*)(\d+)$', name_upper)
    if arp_match:
        key = f"Arp {arp_match.group(1)}"
        if key in ARP_DATABASE:
            return ARP_DATABASE[key]

    # Barnard
    b_match = re.match(r'^(?:B(?:ARNARD)?\s*)(\d+)$', name_upper)
    if b_match:
        key = f"B {b_match.group(1)}"
        if key in EXTENDED_ASTRONOMICAL_DATABASE:
            return EXTENDED_ASTRONOMICAL_DATABASE[key]

    # Caldwell
    c_match = re.match(r'^(?:C(?:ALDWELL)?\s*)(\d+)$', name_upper)
    if c_match:
        num = int(c_match.group(1))
        if 1 <= num <= 109:
            key = f"C {num}"
            if key in EXTENDED_ASTRONOMICAL_DATABASE:
                return EXTENDED_ASTRONOMICAL_DATABASE[key]

    return None


def resolve_target_simbad(raw_name: str, timeout: float = 10.0) -> Optional[Dict[str, Any]]:
    """
    Resolve a target name using SIMBAD online service.
    Returns dict with: name, main_id, ra, dec, type, aliases.
    """
    try:
        from astroquery.simbad import Simbad

        simbad = Simbad()
        simbad.TIMEOUT = timeout
        simbad.add_votable_fields('otype', 'ra(d)', 'dec(d)')

        result = simbad.query_object(raw_name)

        if result is None or len(result) == 0:
            return None

        row = result[0]
        info = {
            'name': raw_name,
            'main_id': str(row.get('MAIN_ID', raw_name)).strip(),
            'ra': float(row['RA_d']) if 'RA_d' in row.colnames else None,
            'dec': float(row['DEC_d']) if 'DEC_d' in row.colnames else None,
            'object_type': str(row.get('OTYPE', 'Unknown')).strip(),
        }

        # Get aliases
        try:
            ids_result = simbad.query_objectids(raw_name)
            if ids_result:
                info['aliases'] = [str(r['ID']).strip() for r in ids_result]
            else:
                info['aliases'] = []
        except Exception:
            info['aliases'] = []

        return info

    except ImportError:
        logger.warning("astroquery not available for SIMBAD resolution")
        return None
    except Exception as e:
        logger.debug(f"SIMBAD query failed for '{raw_name}': {e}")
        return None


def are_same_target(name1: str, name2: str) -> bool:
    """
    Check if two target names refer to the same object.
    Uses local catalogs and SIMBAD cross-referencing.
    """
    if not name1 or not name2:
        return False

    n1 = name1.strip().upper()
    n2 = name2.strip().upper()

    # Direct match
    if n1 == n2:
        return True

    # Known equivalences from Messier catalog
    # Build reverse mapping: common name -> all designations
    equivalences = _build_equivalence_map()

    # Check if both names map to same equivalence group
    g1 = equivalences.get(n1)
    g2 = equivalences.get(n2)

    if g1 is not None and g1 == g2:
        return True

    return False


def _build_equivalence_map() -> Dict[str, int]:
    """Build equivalence groups from catalog cross-references."""
    groups = {}
    group_id = 0

    # Messier to NGC/IC cross-references (data not in MESSIER_DATABASE values)
    _MESSIER_CROSS_REF = {
        'M1': ['NGC 1952'], 'M2': ['NGC 7089'], 'M3': ['NGC 5272'],
        'M4': ['NGC 6121'], 'M5': ['NGC 5904'], 'M6': ['NGC 6405'],
        'M7': ['NGC 6475'], 'M8': ['NGC 6523'], 'M9': ['NGC 6333'],
        'M10': ['NGC 6254'], 'M11': ['NGC 6705'], 'M12': ['NGC 6218'],
        'M13': ['NGC 6205'], 'M14': ['NGC 6402'], 'M15': ['NGC 7078'],
        'M16': ['NGC 6611'], 'M17': ['NGC 6618'], 'M18': ['NGC 6613'],
        'M19': ['NGC 6273'], 'M20': ['NGC 6514'], 'M21': ['NGC 6531'],
        'M22': ['NGC 6656'], 'M23': ['NGC 6494'], 'M24': ['IC 4715'],
        'M25': ['IC 4725'], 'M26': ['NGC 6694'], 'M27': ['NGC 6853'],
        'M28': ['NGC 6626'], 'M29': ['NGC 6913'], 'M30': ['NGC 7099'],
        'M31': ['NGC 224'], 'M32': ['NGC 221'], 'M33': ['NGC 598'],
        'M34': ['NGC 1039'], 'M35': ['NGC 2168'], 'M36': ['NGC 1960'],
        'M37': ['NGC 2099'], 'M38': ['NGC 1912'], 'M39': ['NGC 7092'],
        'M40': [], 'M41': ['NGC 2287'], 'M42': ['NGC 1976'],
        'M43': ['NGC 1982'], 'M44': ['NGC 2632'], 'M45': [],
        'M46': ['NGC 2437'], 'M47': ['NGC 2422'], 'M48': ['NGC 2548'],
        'M49': ['NGC 4472'], 'M50': ['NGC 2323'], 'M51': ['NGC 5194'],
        'M52': ['NGC 7654'], 'M53': ['NGC 5024'], 'M54': ['NGC 6715'],
        'M55': ['NGC 6809'], 'M56': ['NGC 6779'], 'M57': ['NGC 6720'],
        'M58': ['NGC 4579'], 'M59': ['NGC 4621'], 'M60': ['NGC 4649'],
        'M61': ['NGC 4303'], 'M62': ['NGC 6266'], 'M63': ['NGC 5055'],
        'M64': ['NGC 4826'], 'M65': ['NGC 3623'], 'M66': ['NGC 3627'],
        'M67': ['NGC 2682'], 'M68': ['NGC 4590'], 'M69': ['NGC 6637'],
        'M70': ['NGC 6681'], 'M71': ['NGC 6838'], 'M72': ['NGC 6981'],
        'M73': ['NGC 6994'], 'M74': ['NGC 628'], 'M75': ['NGC 6864'],
        'M76': ['NGC 650', 'NGC 651'], 'M77': ['NGC 1068'],
        'M78': ['NGC 2068'], 'M79': ['NGC 1904'], 'M80': ['NGC 6093'],
        'M81': ['NGC 3031'], 'M82': ['NGC 3034'], 'M83': ['NGC 5236'],
        'M84': ['NGC 4374'], 'M85': ['NGC 4382'], 'M86': ['NGC 4406'],
        'M87': ['NGC 4486'], 'M88': ['NGC 4501'], 'M89': ['NGC 4552'],
        'M90': ['NGC 4569'], 'M91': ['NGC 4548'], 'M92': ['NGC 6341'],
        'M93': ['NGC 2447'], 'M94': ['NGC 4736'], 'M95': ['NGC 3351'],
        'M96': ['NGC 3368'], 'M97': ['NGC 3587'], 'M98': ['NGC 4192'],
        'M99': ['NGC 4254'], 'M100': ['NGC 4321'], 'M101': ['NGC 5457'],
        'M102': ['NGC 5866'], 'M103': ['NGC 581'], 'M104': ['NGC 4594'],
        'M105': ['NGC 3379'], 'M106': ['NGC 4258'], 'M107': ['NGC 6171'],
        'M108': ['NGC 3556'], 'M109': ['NGC 3992'], 'M110': ['NGC 205'],
    }

    # Parse Messier entries with cross-references
    for m_key, full_name in MESSIER_DATABASE.items():
        group_id += 1
        m_upper = m_key.upper()
        groups[m_upper] = group_id

        # Add NGC/IC cross-references from table
        for xref in _MESSIER_CROSS_REF.get(m_key, []):
            xref_upper = xref.upper()
            groups[xref_upper] = group_id
            groups[xref_upper.replace(' ', '')] = group_id

        # Extract common names from parentheses
        # Format: "M 31 (Andromeda Galaxy)" or "M 1 (Crab Nebula)"
        name_match = re.search(r'\((.+?)\)$', full_name)
        if name_match:
            common = name_match.group(1).strip().upper()
            groups[common] = group_id

    return groups


def classify_target_type(name: str) -> str:
    """
    Classify a target into a type based on name patterns and catalogs.
    Returns one of the keys from TARGET_TYPES.
    """
    if not name:
        return 'unknown'

    name_upper = name.strip().upper()

    # Solar system
    if name_upper in SOLAR_SYSTEM_OBJECTS:
        return 'planetary'
    if re.match(r'^C/\d{4}', name):  # Comet designation
        return 'comet'

    # Check catalog-specific patterns
    full_name = resolve_target_name(name) or ''
    full_upper = full_name.upper()

    # Type keywords in resolved name
    type_keywords = {
        'galaxy': ['GALAXY', 'GALAX'],
        'emission_nebula': ['EMISSION NEBULA', 'HII REGION', 'H II'],
        'planetary_nebula': ['PLANETARY NEBULA', 'PN '],
        'reflection_nebula': ['REFLECTION NEBULA'],
        'dark_nebula': ['DARK NEBULA', 'BARNARD'],
        'supernova_remnant': ['SUPERNOVA REMNANT', 'SNR'],
        'open_cluster': ['OPEN CLUSTER'],
        'globular_cluster': ['GLOBULAR CLUSTER'],
        'nebula': ['NEBULA', 'NEBUL'],
        'galaxy_group': ['GALAXY GROUP', 'GALAXY CLUSTER', 'ABELL'],
        'double_star': ['DOUBLE STAR'],
    }

    for target_type, keywords in type_keywords.items():
        for kw in keywords:
            if kw in full_upper:
                return target_type

    # Catalog-based classification
    if re.match(r'^SH2', name_upper) or re.match(r'^LBN', name_upper):
        return 'emission_nebula'
    if re.match(r'^ARP', name_upper):
        return 'galaxy'
    if re.match(r'^ABELL', name_upper):
        return 'galaxy_group'
    if re.match(r'^RCW', name_upper):
        return 'emission_nebula'

    return 'unknown'


def is_calibration_target(name: str) -> bool:
    """Check if a target name indicates calibration data (not a real target)."""
    if not name:
        return False
    name_upper = name.strip().upper()
    calibration_keywords = [
        'BIAS', 'DARK', 'FLAT', 'CALIBRATION', 'MASTER', 'OFFSET',
        'FLATWIZARD', 'FLAT_WIZARD', 'SKYFLAT', 'DOMEFLAT',
        'TEST', 'FOCUS', 'AUTOFOCUS',
    ]
    return any(kw in name_upper for kw in calibration_keywords)


def search_catalogs(query: str, max_results: int = 20) -> List[Tuple[str, str]]:
    """
    Search all catalogs for objects matching a query.
    Returns list of (catalog_key, full_name) tuples.
    """
    results = []
    query_upper = query.strip().upper()

    all_dbs = [
        ('Messier', MESSIER_DATABASE),
        ('Extended', EXTENDED_ASTRONOMICAL_DATABASE),
        ('Arp', ARP_DATABASE),
    ]

    for db_name, db in all_dbs:
        for key, full_name in db.items():
            if (query_upper in key.upper() or
                query_upper in full_name.upper()):
                results.append((key, full_name))
                if len(results) >= max_results:
                    return results

    return results

